import os
rows = []
seen = set()
for t in R:
    cik, acc, fn, filer, cp, form, date, exh, dt, vert, notes = t
    accn = acc.replace("-","")
    url = f"https://www.sec.gov/Archives/edgar/data/{int(cik)}/{accn}/{fn}"
    if url in seen:
        continue
    seen.add(url)
    era = "post-2019" if date >= "2019-04-02" else "pre-2019"
    rows.append([url, filer, cp, form, date, exh, dt, vert, era, notes])

os.makedirs("/home/claude/v3_edgar", exist_ok=True)
with open("/home/claude/v3_edgar/manifest.csv","w",newline="") as f:
    w = csv.writer(f)
    w.writerow(["url","filer","counterparty","form","filing_date","exhibit","doc_type","vertical","redaction_era","notes"])
    w.writerows(rows)

print(f"rows: {len(rows)}")
from collections import Counter
print("doc_type:", Counter(r[6] for r in rows))
print("era:", Counter(r[8] for r in rows))
